import { expect, test, uniqueName, sample } from "../../fixtures";

const TAG = "@REV-08";

// The server computes "today" as the UTC date, so derive expiry dates the same way.
function utcDateOffset(days: number): string {
  const d = new Date();
  const utc = new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate() + days));
  return utc.toISOString().slice(0, 10);
}

function insuranceCertificate(expiry: string): string {
  return [
    "Insurer: Harbor Mutual",
    "Policy Number: HM-55-1290",
    "Coverage Amount: $2,000,000",
    `Expiry Date: ${expiry}`,
    "",
  ].join("\n");
}

const rows: Array<{ days: number; include: boolean }> = [
  { days: 0, include: true },
  { days: 30, include: true },
  { days: 31, include: false },
];

test.describe("insurance expiry flags", () => {
  for (const { days, include } of rows) {
    test(
      `insurance expiring in ${days} days ${include ? "is" : "is not"} flagged as expiring soon`,
      { tag: TAG },
      async ({ apiAs }) => {
        // Arrange
        const member = await apiAs("member");
        const createRes = await member.post("/api/vendors", {
          data: {
            name: uniqueName("Flag Test Vendor"),
            category: "logistics",
            contact_email: "ops@flagtest.example",
          },
        });
        expect(createRes.status(), await createRes.text()).toBe(201);
        const vendor = await createRes.json();

        const expiry = utcDateOffset(days);
        const uploadRes = await member.post(`/api/vendors/${vendor.id}/documents`, {
          multipart: {
            kind: "insurance_certificate",
            file: {
              name: "insurance.txt",
              mimeType: "text/plain",
              buffer: Buffer.from(insuranceCertificate(expiry)),
            },
          },
        });
        expect(uploadRes.status(), await uploadRes.text()).toBe(201);
        const document = await uploadRes.json();

        // Flags are only computed once the insurance extraction has finished.
        await expect
          .poll(
            async () => {
              const res = await member.get(`/api/documents/${document.id}`);
              expect(res.status(), await res.text()).toBe(200);
              return (await res.json()).status;
            },
            { timeout: 30_000 },
          )
          .toBe("extracted");

        // Act
        const res = await member.get(`/api/vendors/${vendor.id}`);

        // Assert
        expect(res.status(), await res.text()).toBe(200);
        const body = await res.json();
        if (include) {
          expect(body.flags, `expiry ${expiry}`).toContain("insurance_expiring_soon");
        } else {
          expect(body.flags, `expiry ${expiry}`).not.toContain("insurance_expiring_soon");
        }
      },
    );
  }
});
